  $sections$[{"type":"header","variant":"clasico"},{"type":"hero","variant":"carrusel","botones":{"primary":{"funcion":"seccion","label":"Ver las prendas"},"secondary":{"funcion":"seccion","label":"Guía de talles"}},"looks":[{"id":"look-otonio","season":"Otoño / Invierno 2026","titulo":"Capas que abrigan","desc":"Tapados de paño, sweaters de lana y prendas pensadas para superponer sin volumen de más.","imagen":"https://images.pexels.com/photos/1381556/pexels-photo-1381556.jpeg?auto=compress&cs=tinysrgb&w=1200&h=900&fit=crop"},{"id":"look-basicos","season":"Básicos de temporada","titulo":"Seda y lino","desc":"Camisas amplias en fibras naturales, para usar solas o abajo de todo lo demás.","imagen":"https://images.pexels.com/photos/1926769/pexels-photo-1926769.jpeg?auto=compress&cs=tinysrgb&w=1200&h=900&fit=crop"},{"id":"look-urbana","season":"Cápsula urbana","titulo":"Todos los días","desc":"Las prendas que más se repiten en el placard: remeras de algodón peinado y buzos con cuerpo.","imagen":"https://images.pexels.com/photos/2703202/pexels-photo-2703202.jpeg?auto=compress&cs=tinysrgb&w=1200&h=900&fit=crop"}]},{"type":"beneficios","variant":"franja","items":[{"id":"strip-1","titulo":"Envío gratis desde $120.000"},{"id":"strip-2","titulo":"Primer cambio de talle sin cargo"},{"id":"strip-3","titulo":"3 y 6 cuotas sin interés"},{"id":"strip-4","titulo":"Confección propia en Buenos Aires"}]},{"type":"productos","variant":"moda","eyebrow":"Temporada en curso","titulo":"La colección"},{"type":"guia-talles","eyebrow":"Antes de comprar","titulo":"Guía de talles","descripcion":"Elegí tu talle y mirá las medidas exactas de la prenda, en centímetros y con la prenda apoyada sobre la mesa.","activeColor":"#8fa2ff","talles":[{"id":"talle-s","label":"S","equiv":"Talle 1 · 38","nota":"Si estás entre dos talles y buscás algo entallado, quedate con el S.","medidas":[{"id":"s-busto","label":"Busto","how":"De axila a axila ×2","valor":"96 cm"},{"id":"s-cintura","label":"Cintura","how":"En la parte más angosta","valor":"78 cm"},{"id":"s-largo","label":"Largo total","how":"Del hombro al ruedo","valor":"64 cm"},{"id":"s-hombro","label":"Hombro","how":"De costura a costura","valor":"41 cm"}]},{"id":"talle-m","label":"M","equiv":"Talle 2 · 40","nota":"Es el talle que más se repite. Calce holgado sin quedar suelto.","medidas":[{"id":"m-busto","label":"Busto","how":"De axila a axila ×2","valor":"102 cm"},{"id":"m-cintura","label":"Cintura","how":"En la parte más angosta","valor":"84 cm"},{"id":"m-largo","label":"Largo total","how":"Del hombro al ruedo","valor":"66 cm"},{"id":"m-hombro","label":"Hombro","how":"De costura a costura","valor":"43 cm"}]},{"id":"talle-l","label":"L","equiv":"Talle 3 · 42","nota":"Si te gusta usar la prenda bien suelta, pedí un talle más que el tuyo.","medidas":[{"id":"l-busto","label":"Busto","how":"De axila a axila ×2","valor":"108 cm"},{"id":"l-cintura","label":"Cintura","how":"En la parte más angosta","valor":"90 cm"},{"id":"l-largo","label":"Largo total","how":"Del hombro al ruedo","valor":"68 cm"},{"id":"l-hombro","label":"Hombro","how":"De costura a costura","valor":"45 cm"}]},{"id":"talle-xl","label":"XL","equiv":"Talle 4 · 44","nota":"Hacemos talles especiales a pedido, con dos semanas de anticipación.","medidas":[{"id":"xl-busto","label":"Busto","how":"De axila a axila ×2","valor":"114 cm"},{"id":"xl-cintura","label":"Cintura","how":"En la parte más angosta","valor":"96 cm"},{"id":"xl-largo","label":"Largo total","how":"Del hombro al ruedo","valor":"70 cm"},{"id":"xl-hombro","label":"Hombro","how":"De costura a costura","valor":"47 cm"}]}]},{"type":"pasos","variant":"sticky","numeroEstilo":"chico","eyebrow":"Para que dure","titulo":"Cómo cuidar tus prendas","descripcion":"Trabajamos con fibras naturales, que piden un poco más de atención y duran muchísimo más. Cuatro cosas que hacen toda la diferencia.","imagen":"https://images.pexels.com/photos/1884584/pexels-photo-1884584.jpeg?auto=compress&cs=tinysrgb&w=700&h=875&fit=crop","pasos":[{"id":"care-1","titulo":"Lavá con agua fría","desc":"A mano o en ciclo delicado, nunca arriba de 30 grados. El agua caliente encoge las fibras naturales."},{"id":"care-2","titulo":"Secá a la sombra","desc":"Extendida y lejos del sol directo, que decolora. El secarropas rompe las fibras de la lana."},{"id":"care-3","titulo":"Planchá del revés","desc":"Con la prenda apenas húmeda y a temperatura media. El lino se plancha mejor mojado."},{"id":"care-4","titulo":"Guardá doblada","desc":"Los sweaters de lana se deforman en la percha. Dobladas y con espacio entre prendas."}]},{"type":"testimonios","variant":"scroll"},{"type":"contacto","variant":"mapa","contactoTitulo":"Showroom","contactoTituloPrincipal":"Probate todo con cita previa","contactoSubtitulo":"Atendemos de a una persona por turno, así tenés el probador y el asesoramiento para vos sola. Coordinás por WhatsApp en el momento."},{"type":"footer","variant":"minimal"}]$sections$::jsonb,
